420	typedef struct {
421	    const char *name;
422	    const char *key;
423	    void *value;
424	    int fail_at;           /* 0 = no injected malloc failure */
425	    int expect_ok;         /* expect rb_insert to return 0 */
426	    int expect_free_count; /* rb_free calls during the faulted insert; -1 = n/a */
427	} insert_case_t;
428	
429	/* Cases 1-3: baseline success, and injected failure on each of
430	 * rb_insert's internal allocations. Order-agnostic about which
431	 * allocation (node struct vs. key copy) fail_at hits -- the header's
432	 * -1 contract must hold identically either way.
433	 *
434	 * expect_free_count mirrors create_cases' reasoning: fail_at=1 fails on the
435	 * very first rb_malloc call (the node struct), before anything else is
436	 * allocated, so cleanup frees nothing (0); fail_at=2 fails on the second call
437	 * (the key copy) after the node struct already succeeded, so cleanup frees
438	 * exactly that one allocation (1). */
439	static const insert_case_t insert_cases[] = {
440	    { "insert_into_empty_success", "alpha", "alpha-value", 0, 1, -1 },
441	    { "insert_fails_first_alloc",  "beta",  "beta-value",  1, 0,  0 },
442	    { "insert_fails_second_alloc", "gamma", "gamma-value", 2, 0,  1 },
443	};
444	
445	static void test_rb_insert(void)
446	{
447	    size_t n = sizeof insert_cases / sizeof insert_cases[0];
448	    /* invariant: each iteration gets a fresh tree, so a case's outcome
449	     * never depends on a prior case's inserts. */
450	    for (size_t i = 0; i < n; i++) {
451	        const insert_case_t *c = &insert_cases[i];
452	        rbtree_t *t = rb_create(NULL);
453	        assert(t);
454	
455	        if (c->fail_at)
456	            fault_malloc_arm(c->fail_at);
457	        int rc = rb_insert(t, c->key, c->value);
458	        if (c->fail_at) {
459	            assert(fault_malloc_free_count() == c->expect_free_count);
460	            fault_malloc_disarm();
461	        }
462	
463	        assert((rc == 0) == c->expect_ok);
464	        assert(rb_size(t) == (size_t)(c->expect_ok ? 1 : 0));
465	        assert(rb_find(t, c->key) == (c->expect_ok ? c->value : NULL));
466	
467	        rb_destroy(t);
468	        printf("ok - %s\n", c->name);
469	    }
470	
471	    /* Case 4: on allocation failure the tree must not call value_free,
472	     * and the caller must retain sole ownership of value. */
473	    {
474	        rbtree_t *t = rb_create(track_free);
475	        assert(t);
476	        for (int fail_at = 1; fail_at <= 2; fail_at++) {
477	            reset_tracking();
478	            char *v = malloc(8);
479	            assert(v);
480	            strcpy(v, "owned");
481	
482	            fault_malloc_arm(fail_at);
483	            int rc = rb_insert(t, "delta", v);
484	            fault_malloc_disarm();
485	
486	            assert(rc == -1);
487	            assert(!was_freed(v));
488	            assert(rb_size(t) == 0);
489	            free(v);   /* caller still owns it; must not double-free */
490	        }
491	        rb_destroy(t);
492	        printf("ok - insert_failure_value_not_consumed\n");
493	    }
494	
495	    /* Case 5: overwriting an existing key frees the old value via
496	     * value_free, keeps size unchanged, and matches by key content (two
497	     * distinct buffers with identical content, not the same pointer). */
498	    {
499	        rbtree_t *t = rb_create(track_free);
500	        assert(t);
501	        reset_tracking();
502	
503	        char key_first[] = "dup";
504	        char key_second[] = "dup";
505	        char *old_value = malloc(8);
506	        char *new_value = malloc(8);
507	        assert(old_value && new_value);
508	        strcpy(old_value, "old");
509	        strcpy(new_value, "new");
510	
511	        assert(rb_insert(t, key_first, old_value) == 0);
512	        assert(rb_insert(t, key_second, new_value) == 0);
513	
514	        assert(rb_size(t) == 1);
515	        assert(was_freed(old_value));
516	        assert(free_occurrences(old_value) == 1); /* not freed twice */
517	        assert(!was_freed(new_value));
518	        assert(rb_find(t, "dup") == new_value);
519	
520	        /* A second overwrite of the same key, armed so the very first
521	         * rb_malloc call would fail: overwriting an existing key must not
522	         * allocate a new node or key copy (the key is already stored), so a
523	         * correct rb_insert makes zero rb_malloc/rb_free calls here and
524	         * still returns 0 despite the arming. An implementation that always
525	         * allocates a fresh node on every insert (even for a duplicate key)
526	         * would either fail here or leak the discarded new node/key. */
527	        int since = freed_count;   /* old_value's slot may get reused below */
528	        char *third_value = malloc(8);
529	        assert(third_value);
530	        strcpy(third_value, "third");
531	        fault_malloc_arm(1);
532	        int rc = rb_insert(t, "dup", third_value);
533	        assert(fault_malloc_free_count() == 0);
534	        fault_malloc_disarm();
535	        assert(rc == 0);
536	
537	        assert(rb_size(t) == 1);
538	        assert(free_occurrences_since(new_value, since) == 1); /* freed once, not twice */
539	        assert(!was_freed_since(third_value, since));
540	        assert(rb_find(t, "dup") == third_value);
541	
542	        /* A couple more surviving entries, so destroy has to walk multiple
543	         * nodes, not just the one left over from the overwrites. */
544	        char *extra1 = malloc(8);
545	        char *extra2 = malloc(8);
546	        assert(extra1 && extra2);
547	        strcpy(extra1, "extra1");
548	        strcpy(extra2, "extra2");
549	        assert(rb_insert(t, "extra-key-1", extra1) == 0);
550	        assert(rb_insert(t, "extra-key-2", extra2) == 0);
551	
552	        /* The repeated overwrite must have updated the existing node in
553	         * place, not left a stale second "dup" node behind: exactly 3
554	         * distinct keys should be visible to both validate and foreach. */
555	        assert(rb_validate(t) == 0);
556	        collect_ctx_t after_overwrite = {0};
557	        rb_foreach(t, collect_cb, &after_overwrite);
558	        assert(after_overwrite.n == 3);
559	
560	        rb_destroy(t);
561	        /* rb_destroy must run value_free on every value still owned by the
562	         * tree, not just the ones already freed by the earlier overwrites. */
563	        assert(was_freed(third_value));
564	        assert(was_freed(extra1));
565	        assert(was_freed(extra2));
566	        assert(freed_count == 5); /* old_value + new_value (overwrites) + 3 by destroy */
567	        printf("ok - insert_overwrite_frees_old_value\n");
568	    }
569	
570	    /* Case 6: distinct keys each get their own slot; size accumulates
571	     * and lookups don't cross-contaminate. Keys are inserted from mutable
572	     * buffers that get scribbled over right after each insert returns --
573	     * if rb_insert stored the caller's pointer instead of rb_malloc+memcpy
574	     * copying it, the lookups below would see the mutated content instead
575	     * of the original key. */
576	    {
577	        rbtree_t *t = rb_create(NULL);
578	        assert(t);
579	        char buf_a[] = "a-key", buf_m[] = "m-key", buf_z[] = "z-key";
580	        assert(rb_insert(t, buf_a, "a-value") == 0);
581	        assert(rb_insert(t, buf_m, "m-value") == 0);
582	        assert(rb_insert(t, buf_z, "z-value") == 0);
583	        memset(buf_a, 'X', strlen(buf_a));
584	        memset(buf_m, 'X', strlen(buf_m));
585	        memset(buf_z, 'X', strlen(buf_z));
586	
587	        assert(rb_size(t) == 3);
588	        assert(strcmp(rb_find(t, "a-key"), "a-value") == 0);
589	        assert(strcmp(rb_find(t, "m-key"), "m-value") == 0);
590	        assert(strcmp(rb_find(t, "z-key"), "z-value") == 0);
591	        assert(rb_find(t, "q-key") == NULL);
592	        assert(rb_find(t, "XXXXX") == NULL);
593	
594	        rb_destroy(t);
595	        printf("ok - insert_distinct_keys_prove_key_copy\n");
596	    }
