598	    /* Case 7: an ascending run of inserts forces left-rotations during
599	     * insert-fixup; rebalancing must preserve red-black invariants and
600	     * BST (sorted in-order) structure. */
601	    {
602	        static const char *keys[] = { "a", "b", "c", "d", "e", "f", "g" };
603	        size_t run_len = sizeof keys / sizeof keys[0];
604	        rbtree_t *t = rb_create(NULL);
605	        assert(t);
606	        /* invariant: every insert in this run succeeds before the next
607	         * begins, so size == i+1 after the i-th insert. */
608	        for (size_t i = 0; i < run_len; i++) {
609	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
610	            assert(rb_size(t) == i + 1);
611	        }
612	
613	        assert(rb_validate(t) == 0);
614	
615	        collect_ctx_t collected = {0};
616	        rb_foreach(t, collect_cb, &collected);
617	        assert(collected.n == (int)run_len);
618	        /* invariant: in-order traversal is strictly ascending since all
619	         * inserted keys are distinct. */
620	        for (int i = 0; i + 1 < collected.n; i++)
621	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
622	        /* invariant: foreach's value for each slot is exactly the pointer
623	         * that was inserted for that key (sorted order == insertion order
624	         * here, since the run was already ascending). */
625	        for (int i = 0; i < collected.n; i++)
626	            assert(collected.values[i] == (void *)keys[i]);
627	
628	        /* Every key must still be reachable by search after the rotations
629	         * this run triggered, not just present in the in-order walk. */
630	        for (size_t i = 0; i < run_len; i++)
631	            assert(rb_find(t, keys[i]) == (void *)keys[i]);
632	
633	        rb_destroy(t);
634	        printf("ok - insert_rebalances_ascending_run\n");
635	    }
