638	     * insert-fixup; same invariants must hold. */
639	    {
640	        static const char *keys[] = { "g", "f", "e", "d", "c", "b", "a" };
641	        size_t run_len = sizeof keys / sizeof keys[0];
642	        rbtree_t *t = rb_create(NULL);
643	        assert(t);
644	        for (size_t i = 0; i < run_len; i++) {
645	            assert(rb_insert(t, keys[i], (void *)keys[i]) == 0);
646	            assert(rb_size(t) == i + 1);
