653	        assert(collected.n == (int)run_len);
654	        for (int i = 0; i + 1 < collected.n; i++)
655	            assert(strcmp(collected.keys[i], collected.keys[i + 1]) < 0);
656	        /* invariant: foreach's value for each slot is exactly the pointer
657	         * that was inserted for that key; sorted order is the reverse of
658	         * this run's (descending) insertion order. */
659	        for (int i = 0; i < collected.n; i++)
