795	    /* Case 12: a minimal RL zig-zag, the mirror of case 11. "a" becomes the
796	     * black root; "c" inserts red as its right child; "b" then inserts red
797	     * as "c"'s left child. "c" is "a"'s right child while "b" is "c"'s left
798	     * child, forcing a right-rotation at "c" then a left-rotation at "a". */
799	    {
800	        static const char *keys[] = { "a", "c", "b" };
801	        const char *sorted[] = { keys[0], keys[2], keys[1] }; /* a, b, c */
802	        size_t run_len = sizeof keys / sizeof keys[0];
