    root->right = target; root->left = sibling;
    root->parent = t->nil;
    target->parent = root; sibling->parent = root;
    sibling->left = nephewFar; sibling->right = nephewNear;
    nephewFar->parent = sibling; nephewNear->parent = sibling;
